import portal.models


def fill_state(apps, schema_editor):
    """Orders recorded before decision 0012 carry Pretix's own status code
    only: give them the normalised state the stats now read."""
    PretixOrder = apps.get_model("attendee", "PretixOrder")
    for order in PretixOrder.objects.filter(state=""):
        if order.status == "p":
            order.state = "paid" if order.total else "free"
        elif order.status in ("c", "e"):
            order.state = "cancelled"
        elif order.status == "n":
            order.state = "pending"
        else:
            continue
        order.save(update_fields=["state"])


